const months=['Agustus','September','Oktober'];const $=id=>document.getElementById(id);const number=n=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(n);const decimal=n=>new Intl.NumberFormat('id-ID',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);const money=n=>'Rp'+number(n);const shortMoney=n=>'Rp'+new Intl.NumberFormat('id-ID',{maximumFractionDigits:2}).format(n/1e6)+' jt';let chartMetric='roas';
function state(){return {i:$('period').value==='oct'?2:1,photo:$('source').value==='photo'}}
function total(i){return products.reduce((a,p)=>{for(const k of ['units','spend','clicks','orders','views'])a[k]+=p[k][i];a.sales+=p.units[i]*p.price;return a},{units:0,spend:0,clicks:0,orders:0,views:0,sales:0})}
function pct(n,p){return p?(n/p-1)*100:null}function change(n,p){const v=pct(n,p);return v===null?'—':(v>=0?'+':'')+new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(v)+'%'}
function delta(n,p,invert=false){const v=pct(n,p);return `<span class="delta ${v===null?'neutral':(invert?v>0:v<0)?'down':''}">${change(n,p)}</span>`}
function render(){const {i,photo}=state(),a=total(i),b=total(i-1),r=a.sales/a.spend,old=b.sales/b.spend;document.querySelector('.demotag').textContent=photo?'DATA FOTO ASLI':'DATA SIMULASI';$('period').disabled=photo;$('compare').textContent=photo?'29 Sep–5 Okt 2026 (WIB)':`vs 1–5 ${months[i-1]} 2026`;$('notice').innerHTML=photo?'Sesuai foto: seluruh metrik bernilai 0 untuk 29 September–5 Oktober 2026. Data per produk dan periode pembanding belum tersedia.':'<strong>Preview dengan data simulasi.</strong> Nama produk, foto ilustrasi, dan angka adalah contoh, bukan data toko. Perbandingan memakai tanggal 1–5 di kedua bulan.';
$('summaryTitle').textContent=photo?'Belum ada performa iklan yang tercatat.':`Penjualan ${change(a.sales,b.sales)}, dengan biaya iklan ${change(a.spend,b.spend)}.`;
$('summaryText').textContent=photo?'Unggah laporan Shopee melalui percakapan untuk mengisi versi berikutnya dengan angka sebenarnya.':`ROAS ${decimal(r)}× (${change(r,old)}). ${[...products].sort((x,y)=>y.units[i]-x.units[i])[0].name} menjadi produk terlaris periode ini.`;
$('summaryPill').textContent=photo?'Data belum lengkap':r>old?'Efisiensi meningkat':'Evaluasi efisiensi';$('periodNote').textContent=photo?'29 Sep–5 Okt 2026':'1–5 '+months[i]+' 2026 • WIB';
const metrics=[['Iklan dilihat',a.views,b.views,number,'◉'],['Jumlah klik',a.clicks,b.clicks,number,'↖'],['Persentase klik (CTR)',a.clicks/a.views*100,b.clicks/b.views*100,n=>decimal(n)+'%','%'],['Pesanan',a.orders,b.orders,number,'▣'],['Produk terjual',a.units,b.units,number,'▦'],['Penjualan',a.sales,b.sales,shortMoney,'↗'],['Biaya iklan',a.spend,b.spend,shortMoney,'▤'],['ROAS',r,old,n=>decimal(n)+'×','◎']];
$('metrics').innerHTML=metrics.map(([name,n,p,fmt,icon],idx)=>`<article class="metric ${idx===7?'featured':''}"><div class="metriclabel">${name}<span aria-hidden="true" class="miniicon">${icon}</span></div><div class="metricvalue" title="${idx===5||idx===6?money(photo?0:n):fmt(photo?0:n)}">${photo?(idx===5||idx===6?'Rp0':fmt(0)):fmt(n)}</div><div class="metricchange">${photo?'Pembanding belum tersedia':delta(n,p,idx===6)+'vs periode sebelumnya'}</div></article>`).join('');
$('roasComparison').innerHTML=photo?'<div class="empty">ROAS pada foto: <strong>0,00×</strong><br>Periode pembanding belum tersedia.</div>':[[months[i],r,false],[months[i-1],old,true]].map(([name,val,prior])=>`<div class="roasline"><div class="roaslabels"><span>1–5 ${name}</span><strong>${decimal(val)}×</strong></div><div class="bartrack"><div class="barfill ${prior?'previous':''}" style="width:${val/Math.max(r,old)*100}%"></div></div></div>`).join('');
$('roasInsight').innerHTML=photo?'Belum cukup data untuk menilai efisiensi.':`<strong>${r>old?'↗':'↘'} ${decimal(Math.abs(r-old))} poin ROAS (${change(r,old)})</strong>Setiap Rp1 biaya iklan menghasilkan Rp${decimal(r)} penjualan teratribusi pada periode ini.`;
$('footerNote').textContent=photo?'Sumber: foto performa Shopee • 29 Sep–5 Okt 2026':'Snapshot simulasi • 1–5 '+months[i]+' 2026 • WIB';renderChart();renderProducts();renderMomentum();renderBestsellers();}
function renderChart(){const {i,photo}=state();$('currentLegend').textContent=photo?'29 Sep–5 Okt':months[i];$('priorLegend').textContent=photo?'Tanpa pembanding':months[i-1];$('chartSub').textContent=photo?'Seluruh angka pada foto bernilai nol':'Perbandingan harian pada tanggal 1–5';let curr=[],prev=[];const weights=[[.17,.18,.21,.20,.24],[.19,.21,.17,.23,.20],[.16,.20,.19,.22,.23]],spendWeights=[[.20,.19,.21,.18,.22],[.21,.19,.21,.20,.19],[.20,.19,.20,.20,.21]];for(let day=0;day<5;day++){for(const [idx,target] of [[i,curr],[i-1,prev]]){const t=total(idx);target.push(chartMetric==='roas'?t.sales*weights[idx][day]/(t.spend*spendWeights[idx][day]):chartMetric==='sales'?t.sales*weights[idx][day]:t.clicks*weights[idx][day])}}if(photo){curr=Array(7).fill(0);prev=[]}const max=Math.max(...curr,...prev,1)*1.17,W=660,H=190,L=45,R=15,B=29,T=14;const x=k=>L+k*(W-L-R)/(curr.length-1),y=v=>H-B-v/max*(H-B-T);const format=n=>chartMetric==='roas'?new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(n)+'×':chartMetric==='sales'?new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(n/1e6)+' jt':number(n);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Grafik ${chartMetric}, ${photo?'semua nilai nol':'data simulasi '+months[i]+' dan '+months[i-1]}"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#f57951" stop-opacity=".13"/><stop offset="1" stop-color="#f57951" stop-opacity="0"/></linearGradient></defs>`;for(let j=0;j<4;j++){const val=max*j/3;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(val)}" y2="${y(val)}" stroke="#edf0f3" stroke-dasharray="3 4"/><text x="${L-10}" y="${y(val)+4}" text-anchor="end" font-size="10" fill="#9ca4ad">${format(val)}</text>`}const path=arr=>arr.map((v,k)=>`${k?'L':'M'}${x(k)},${y(v)}`).join(' ');svg+=`<path d="${path(curr)} L${x(curr.length-1)},${H-B} L${L},${H-B} Z" fill="url(#fade)"/>`;if(prev.length)svg+=`<path d="${path(prev)}" stroke="#b9c3ce" stroke-width="2" fill="none" stroke-dasharray="5 5"/>`;svg+=`<path d="${path(curr)}" stroke="#ed5935" stroke-width="2.5" stroke-linejoin="round" fill="none"/>`;curr.forEach((v,k)=>{svg+=`<circle cx="${x(k)}" cy="${y(v)}" r="3.5" fill="white" stroke="#ed5935" stroke-width="2"><title>${photo?['29 Sep','30 Sep','1 Okt','2 Okt','3 Okt','4 Okt','5 Okt'][k]:k+1+' '+months[i]}: ${format(v)}</title></circle><text x="${x(k)}" y="${H-6}" text-anchor="middle" fill="#9ca4ad" font-size="10">${photo?['29 Sep','30 Sep','1 Okt','2 Okt','3 Okt','4 Okt','5 Okt'][k]:`0${k+1} ${months[i].slice(0,3)}`}</text>`});$('chart').innerHTML=svg+'</svg>';}
function renderProducts(){const {i,photo}=state();const q=$('search').value.trim().toLowerCase();const sort=$('sort').value;let list=photo?[]:products.filter(p=>(p.name+' '+p.id).toLowerCase().includes(q));list.sort((a,b)=>sort==='units'?b.units[i]-a.units[i]:sort==='sales'?b.units[i]*b.price-a.units[i]*a.price:b.units[i]*b.price/b.spend[i]-a.units[i]*a.price/a.spend[i]);$('productRows').innerHTML=list.length?list.map((p,k)=>{const v=pct(p.units[i],p.units[i-1]);return `<tr><td><div class="productcell"><span class="rank">${String(k+1).padStart(2,'0')}</span><span class="productthumb">${productImage(p)}</span><div><button class="productname" data-id="${p.id}">${p.name}</button><small>${p.id}</small></div></div></td><td><strong>${number(p.units[i])}</strong> <span style="color:#939aa2">unit</span></td><td>${money(p.units[i]*p.price)}</td><td>${money(p.spend[i])}</td><td><span class="roasbadge">${decimal(p.units[i]*p.price/p.spend[i])}×</span></td><td>${delta(p.units[i],p.units[i-1])}</td><td><span class="trendbadge ${v>=20?'rise':v<=-15?'fall':''}">${v>=20?'↗ Naik pesat':v<=-15?'↘ Menurun':'Relatif stabil'}</span></td></tr>`}).join(''):`<tr><td colspan="7" class="empty">${photo?'Data per produk tidak tersedia pada foto.':'Tidak ada produk yang cocok dengan pencarian.'}</td></tr>`;$('tableCount').textContent=photo?'Belum ada rincian produk':`${list.length} dari ${products.length} produk simulasi`;$('products').querySelector('.count').textContent=photo?'Belum tersedia':'6 produk';}
function renderMomentum(){const {i,photo}=state();if(photo){$('momentumCards').innerHTML='<article class="momentumcard" style="grid-column:1/-1"><h3>Pergerakan belum dapat dianalisis</h3><p>Diperlukan jumlah produk terjual pada dua periode yang sebanding.</p></article>';$('rankTitle').textContent='Peringkat belum tersedia';$('rankText').textContent='Foto hanya memuat ringkasan akun.';$('rankFlow').innerHTML='';$('actions').innerHTML='<article class="action" style="grid-column:1/-1"><span class="actionnum">01</span><div><h3>Lengkapi laporan iklan per produk</h3><p>Kirim nama produk, tayangan, klik, pesanan, unit terjual, penjualan, dan biaya iklan untuk periode berjalan serta periode pembanding. Data ini diperlukan agar rekomendasi didasarkan pada hasil toko.</p></div></article>';return}const ranked=[...products].sort((a,b)=>pct(b.units[i],b.units[i-1])-pct(a.units[i],a.units[i-1]));const rising=ranked[0],stable=products.find(p=>Math.abs(pct(p.units[i],p.units[i-1]))<15)||ranked[2],falling=ranked[ranked.length-1];const previous=[...products].sort((a,b)=>b.units[i-1]-a.units[i-1])[0],current=[...products].sort((a,b)=>b.units[i]-a.units[i])[0];$('momentumCards').innerHTML=[[rising,'Mulai melesat','↗',`Pertumbuhan tercepat periode ini. ROAS ${decimal(rising.units[i]*rising.price/rising.spend[i])}×; cek stok sebelum menambah anggaran.`],[stable,'Menjaga konsistensi','≈','Perubahan unit dalam rentang −15% hingga +20%. Pantau efisiensi biaya sambil menjaga ketersediaan produk.'],[falling,'Perlu perhatian','↘',`Penjualan unit ${change(falling.units[i],falling.units[i-1])}. Tinjau materi iklan, harga, dan ketersediaan ukuran untuk mencari penyebabnya.`]].map(([p,title,icon,text])=>`<article class="momentumcard"><div class="momentumheading"><span>${icon}</span>${title}</div><h3>${p.name}</h3><div class="momentumstats"><span>${p.units[i-1]} → <strong>${p.units[i]} unit</strong></span>${delta(p.units[i],p.units[i-1])}</div><p>${text}</p></article>`).join('');$('rankTitle').textContent=previous===current?`${current.name} mempertahankan posisi #1.`:`${current.name} mengambil posisi #1.`;$('rankText').textContent=`${previous.name}: ${previous.units[i-1]} → ${previous.units[i]} unit. ${previous===current?'Tetap memimpin volume penjualan iklan.':current.name+': '+current.units[i-1]+' → '+current.units[i]+' unit.'}`;$('rankFlow').innerHTML=`<div class="rankitem"><small>#1 • ${months[i-1]}</small>${previous.name}</div><span>→</span><div class="rankitem"><small>#1 • ${months[i]}</small>${current.name}</div>`;$('actions').innerHTML=[['Pertahankan produk pemimpin',`${current.name} menyumbang ${new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(current.units[i]*current.price/total(i).sales*100)}% penjualan iklan. Pastikan stok dan margin mendukung sebelum menaikkan anggaran.`,'PRIORITAS TINGGI'],['Uji peluang yang bertumbuh',`${rising.name} naik ${change(rising.units[i],rising.units[i-1])}. Uji tambahan anggaran secara bertahap, lalu evaluasi ROAS dan pesanan.`,'PELUANG PERTUMBUHAN'],['Evaluasi produk yang melambat',`${falling.name} turun ${change(falling.units[i],falling.units[i-1])}. Periksa klik, konversi, stok, dan materi iklan sebelum mengubah strategi.`,'PERLU DITINJAU']].map(([title,text,priority],k)=>`<article class="action"><span class="actionnum">0${k+1}</span><div><h3>${title}</h3><p>${text}</p><span class="priority">${priority}</span></div></article>`).join('');}
$('period').addEventListener('change',render);$('source').addEventListener('change',render);$('search').addEventListener('input',renderProducts);$('sort').addEventListener('change',renderProducts);document.querySelectorAll('[data-chart]').forEach(btn=>btn.addEventListener('click',()=>{chartMetric=btn.dataset.chart;document.querySelectorAll('[data-chart]').forEach(b=>b.classList.toggle('selected',b===btn));renderChart()}));$('print').addEventListener('click',()=>window.print());document.addEventListener('click',event=>{const btn=event.target.closest('[data-id]');if(!btn)return;const p=products.find(x=>x.id===btn.dataset.id),{i}=state();$('detailContent').innerHTML=`<h2>${p.name}</h2><p>${p.id} • Simulasi 1–5 ${months[i]} 2026</p><div class="detailimage">${productImage(p)}${productCatalog[p.id]?.imageUrl?'<span class="imagelabel">Foto ilustrasi</span>':''}</div><div class="detailgrid">${[['Terjual',number(p.units[i])+' unit'],['ROAS',decimal(p.units[i]*p.price/p.spend[i])+'×'],['Penjualan',money(p.units[i]*p.price)],['Biaya iklan',money(p.spend[i])],['Klik',number(p.clicks[i])],['Pesanan',number(p.orders[i])]].map(([name,val])=>`<div><small>${name}</small><strong>${val}</strong></div>`).join('')}</div><p>Periode 1–5 ${months[i-1]}: ${p.units[i-1]} unit, ROAS ${decimal(p.units[i-1]*p.price/p.spend[i-1])}×. Perubahan unit: <strong>${change(p.units[i],p.units[i-1])}</strong>.</p><p style="font-size:12px">Angka simulasi untuk preview. ROAS tidak memperhitungkan modal barang, biaya marketplace, dan biaya operasional.</p>`;$('detail').showModal()});$('closeDetail').addEventListener('click',()=>$('detail').close());$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close()}});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('nav a').forEach(n=>n.classList.toggle('active',n===a))}));render();
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function productImage(product){const entry=productCatalog[product.id];if(!entry?.imageUrl)return '<span class="photomissing">Foto belum tersedia</span>';const raw=entry.imageUrl;const valid=raw.startsWith('assets/')||/^https:\/\//i.test(raw);if(!valid)return '<span class="photomissing">Foto belum tersedia</span>';return `<img class="productphoto" src="${escapeHtml(raw)}" alt="${escapeHtml(entry.imageAlt||product.name)}" loading="lazy" decoding="async" referrerpolicy="no-referrer">`;}
function renderBestsellers(){const {i,photo}=state();const section=$('bestsellers');section.querySelector('.tag').textContent=photo?'DATA PRODUK BELUM TERSEDIA':'FOTO ILUSTRASI • BUKAN PRODUK ASLI';if(photo){$('bestsellerCards').innerHTML='<div class="panel empty" style="grid-column:1/-1">Foto performa akun tidak memuat nama atau gambar produk. Kirim katalog produk untuk melengkapi bagian ini.</div>';return}const list=[...products].sort((a,b)=>b.units[i]-a.units[i]).slice(0,3);$('bestsellerCards').innerHTML=list.map((p,k)=>`<article class="bestcard"><div class="bestimage">${productImage(p)}<span class="bestnumber">#${k+1} Best seller</span>${productCatalog[p.id]?.imageUrl?'<span class="imagelabel">Foto ilustrasi</span>':''}</div><div class="bestbody"><h3><button class="productname" data-id="${p.id}">${p.name}</button></h3><span class="bestsku">${p.id}</span><div class="beststats"><div><small>Terjual</small><strong>${number(p.units[i])} <span style="font-size:12px;font-weight:400">unit</span></strong></div><div><small>ROAS</small><strong>${decimal(p.units[i]*p.price/p.spend[i])}×</strong></div></div><div class="bestfoot"><span>${shortMoney(p.units[i]*p.price)} penjualan</span>${delta(p.units[i],p.units[i-1])}</div></div></article>`).join('');}
document.addEventListener('error',event=>{const img=event.target;if(img?.classList?.contains('productphoto')){const fallback=document.createElement('span');fallback.className='photomissing';fallback.textContent='Foto tidak dapat dimuat';img.replaceWith(fallback)}},true);
